// Get the raw text from AI Agent output
let raw = $json.output || "";

// Remove markdown code fences
raw = raw.replace(/```json|```/g, "").trim();

// Parse into JSON
let parsed = JSON.parse(raw);

// Return as an item
return parsed;

// Loop over all input items
const results = [];

for (const item of $input.all()) {
  const docs = item.json.docs || [];
  const mapped = {};

  docs.forEach(doc => {
    const doctypeName = doc.name || "";

    // skip unwanted doctypes
    if (
      doctypeName.includes("Custom Item Sales Enquiry") ||
      doctypeName.includes("Sales Taxes and Charges") ||
      doctypeName.includes("Packed Item") ||
      doctypeName.includes("Pricing Rule Detail") ||
      doctypeName.includes("Payment Schedule") ||
      doctypeName.includes("Sales Team")
    ) { 
      return;
    }

    const cleanedFields = (doc.fields || [])
      .filter(f => !["Section Break", "Column Break", "Tab Break"].includes(f.fieldtype))
      .map(f => ({
        fieldname: f.fieldname,
        fieldtype: f.fieldtype,
        options: f.options || "",
        default: f.default || "",
        reqd: f.reqd || 0,
        label: f.label,
        idx: f.idx,
      }));

    // add doctype as a key in the object
    mapped[doctypeName] = cleanedFields;
  });

  results.push({ data: mapped });
}

// Return cleaned JSON for each item
return results;

